def splitIntoThreePalindromes(s):
    length = len(s)
    for i in range(1, length-1):
        for j in range(i+1, length):
            a, b, c = splitAt(s, i), splitAt(s, j)
            if a[0] == b[0] == c[0] and a[1][::-1] == a[1] and b[1][::-1] == b[1] and c[1][::-1] == c[1]:
                return True
    return False

